// Combine and parse all RSS feeds into structured news items
const allItems = [];

// Helper to parse RSS XML
function parseRSS(xmlText, source) {
  const items = [];
  const itemRegex = /<item>(.*?)<\/item>/gs;
  const titleRegex = /<title><!\[CDATA\[(.*?)\]\]>|<title>(.*?)<\/title>/;
  const linkRegex = /<link>(.*?)<\/link>/;
  const pubDateRegex = /<pubDate>(.*?)<\/pubDate>/;
  const descRegex = /<description><!\[CDATA\[(.*?)\]\]>|<description>(.*?)<\/description>/;

  let match;
  while ((match = itemRegex.exec(xmlText)) !== null) {
    const itemXml = match[1];
    const titleMatch = titleRegex.exec(itemXml);
    const linkMatch = linkRegex.exec(itemXml);
    const dateMatch = pubDateRegex.exec(itemXml);
    const descMatch = descRegex.exec(itemXml);

    items.push({
      title: titleMatch ? (titleMatch[1] || titleMatch[2] || '').trim() : '',
      link: linkMatch ? linkMatch[1].trim() : '',
      pubDate: dateMatch ? dateMatch[1].trim() : '',
      description: descMatch ? (descMatch[1] || descMatch[2] || '').substring(0, 500) : '',
      source: source
    });
  }
  return items;
}

// Process each input
for (const item of $input.all()) {
  const data = item.json.data || item.json.body || item.json;
  if (typeof data === 'string' && data.includes('<')) {
    const source = item.json.source || 'unknown';
    const parsed = parseRSS(data, source);
    allItems.push(...parsed);
  }
}

// Deduplicate by title similarity and sort by date
const seen = new Set();
const uniqueItems = allItems.filter(item => {
  const key = item.title.toLowerCase().substring(0, 50);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));

// Take top 50 most recent
const topNews = uniqueItems.slice(0, 50);

return [{
  json: {
    newsCount: topNews.length,
    fetchedAt: new Date().toISOString(),
    news: topNews
  }
}];

