// Parse Gemini response and determine if alert is needed
const response = $input.first().json;
let analysis;

try {
  // Extract the text content from Gemini response
  const textContent = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  analysis = JSON.parse(textContent);
} catch (e) {
  analysis = {
    urgencyScore: 5,
    keyThemes: ['Unable to parse response'],
    marketImpact: 'Analysis unavailable',
    sectorAlerts: {},
    commoditiesOutlook: 'Unknown',
    riskAssessment: 'Unknown'
  };
}

const urgencyScore = analysis.urgencyScore || 5;
const needsImmediateAlert = urgencyScore >= 8;
const isWeeklyReportDay = new Date().getDay() === 0; // Sunday

return [{
  json: {
    ...analysis,
    urgencyScore,
    needsImmediateAlert,
    isWeeklyReportDay,
    analyzedAt: new Date().toISOString(),
    originalNews: $('Aggregate & Parse News').first().json.news
  }
}];

