// Store the alert in knowledge base format
const analysis = $('Process Analysis Result').first().json;
const alertContent = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';

const report = {
  type: 'URGENT_ALERT',
  date: new Date().toISOString(),
  urgencyScore: analysis.urgencyScore,
  keyThemes: analysis.keyThemes,
  marketImpact: analysis.marketImpact,
  sectorAlerts: analysis.sectorAlerts,
  commoditiesOutlook: analysis.commoditiesOutlook,
  riskAssessment: analysis.riskAssessment,
  alertContent: alertContent,
  newsItems: analysis.originalNews?.slice(0, 10) || []
};

return [{ json: report }];

// Store daily analysis in memory for weekly aggregation
const analysis = $input.first().json;

const dailyReport = {
  type: 'DAILY_ANALYSIS',
  date: new Date().toISOString(),
  urgencyScore: analysis.urgencyScore,
  keyThemes: analysis.keyThemes,
  marketImpact: analysis.marketImpact,
  sectorAlerts: analysis.sectorAlerts,
  commoditiesOutlook: analysis.commoditiesOutlook,
  riskAssessment: analysis.riskAssessment,
  newsCount: analysis.originalNews?.length || 0
};

return [{ json: dailyReport }];

// Format weekly report for GitHub storage
const reportHtml = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const weekNumber = Math.ceil((new Date() - new Date(new Date().getFullYear(), 0, 1)) / 604800000);
const year = new Date().getFullYear();

const report = {
  type: 'WEEKLY_REPORT',
  year: year,
  week: weekNumber,
  date: new Date().toISOString(),
  filename: `reports/${year}/week_${weekNumber.toString().padStart(2, '0')}.md`,
  content: reportHtml
};

return [{ json: report }];

// Check VIX level for volatility alerts
const vixData = $input.first().json;
let currentVix = 0;
let vixChange = 0;

try {
  const quotes = vixData.chart?.result?.[0]?.indicators?.quote?.[0];
  const closes = quotes?.close || [];
  currentVix = closes[closes.length - 1] || 0;
  const prevVix = closes[closes.length - 2] || currentVix;
  vixChange = ((currentVix - prevVix) / prevVix * 100).toFixed(2);
} catch (e) {
  currentVix = 0;
}

return [{
  json: {
    currentVix,
    vixChange,
    vixAlert: currentVix > 25,
    vixSpike: vixChange > 20,
    fetchedAt: new Date().toISOString()
  }
}];

// Merge VIX data with news before analysis
const newsData = $('Aggregate & Parse News').first().json;
const vixData = $('Process VIX Data').first().json;

return [{
  json: {
    ...newsData,
    vix: vixData,
    marketData: {
      vixLevel: vixData.currentVix,
      vixAlert: vixData.vixAlert,
      vixSpike: vixData.vixSpike
    }
  }
}];
